window.MONSTER_CHUNK_93 = [{"name":"The Old Man","cr":15,"xp":51200,"alignment":"LN","size":"Medium","type":"outsider","subtypes":["extraplanar","herald","lawful"],"init":10,"senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":37,"ac_touch":35,"ac_flat_footed":26,"ac_mods":"+10 Dex, +1 dodge, +4 monk, +10 Wis, +2 natural","hp":178,"hd":"17d10+85","hdvalue":17,"hp_mods":["regeneration 15 (chaotic)"],"fort":10,"ref":20,"will":20,"defensive_abilities":["improved evasion"],"dr":"10/chaotic","immunities":["disease","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"electricity","value":30},{"type":"fire","value":30},{"type":"sonic","value":30}],"sr":26,"speed":[{"type":"land","speed":80},{"type":"climb","speed":30},{"type":"swim","speed":30}],"melee":"unarmed strike +27 (2d8+5) or  flurry of blows  +20  (2d8+5)","ranged":"pebble +27  (1d3+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"stunning fist","details":"16/day, DC 28"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"commune"},{"spell":"haste"},{"spell":"heal"},{"spell":"legend lore"}]},{"frequency":"7/day","spells":[{"spell":"air walk"},{"spell":"augury"},{"spell":"cure light wounds"},{"spell":"dimension door"},{"spell":"invisibility"},{"spell":"true strike"},{"spell":"water walk"}]}],"strength":20,"dexterity":31,"constitution":20,"intelligence":21,"wisdom":31,"charisma":22,"baseatk":17,"cmb":54,"cmd":71,"cmd_special":"+4 vs. trip","feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Greater Grapple"},{"feat":"Improved Disarm"},{"feat":"Improved Grapple"},{"feat":"Improved Trip"},{"feat":"Improved Unarmed Strike","type":"bonus"},{"feat":"Mobility"},{"feat":"Stunning Fist","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Wind Stance"}],"skills":[{"skill":"Acrobatics","value":30,"special":"+66 when jumping"},{"skill":"Climb","value":13},{"skill":"Diplomacy","value":23},{"skill":"Handle Animal","value":14},{"skill":"Heal","value":22},{"skill":"Knowledge (history)","value":22},{"skill":"Knowledge (religion)","value":13},{"skill":"Perception","value":30},{"skill":"Perform (string)","value":23},{"skill":"Ride","value":27},{"skill":"Sense Motive","value":30},{"skill":"Sleight of Hand","value":30},{"skill":"Stealth","value":30},{"skill":"Swim","value":25}],"languages":["Common","Tien","Vudrani","telepathy 100 ft."],"sq":[{"type":"monk abilities"}],"environments":["any land (Axis)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This bald old human man has long white eyebrows and an even longer white beard. He carries a staff adorned with metal rings.","source":"Inner Sea Gods","special_abilities":[{"type":"Monk Abilities","kind":"Ex or Su","details":"The Old Man has the following abilities of a 16th-level monk: AC bonus (+4), fast movement (50 ft.), flurry of blows, high jump, ki pool (18 points, adamantine, cold iron, lawful, magic, silver), quivering palm (DC 28), slow fall (80 ft.), stunning fist (blinded, deafened, fatigued, staggered, or stunned), unarmed strike."}],"description":"The Old Man is the herald of Irori, a teacher, mentor, guide, and trainer in the service of the god of knowledge, history, and self-perfection. He can be patient or irate, confusing or enlightening, lenient or strict, depending on what his students need. He often wanders Golarion as a mortal man, bereft of his supernatural powers, instructing others and leading by example. If attacked when in this limited shape, he usually allows himself to be beaten or killed, especially if his \"death\" would provide a powerful lesson to an important student. If slain as a mortal, he simply reincarnates in his celestial form, unharmed, and never bears a grudge about it.\n\nThe Old Man's true form is that of an elderly human man, perhaps of Tien or Vudrani ancestry but never clearly identifiable as such. He is typically bald and wiry, and usually wears a long white moustache or beard. Though he appears frail and sometimes supports himself with a cane, crutch, or staff, he is incredibly strong and can move with an alien grace when he so chooses. He may dress in a simple robe, an elaborate ceremonial garment, or a simple loincloth.\n\nHe is often accompanied by one of five animals: a turtle, monkey, ox, rooster, or pig.\n\nWhen not acting on Irori's behalf, the Herald of Irori keeps busy with tending to animals, planting gardens, meditating, practicing martial arts forms, swimming, and quipping with students.\n\nThe Herald of Irori stands just over 5 ft. tall and weighs about 120 pounds.","ecology":"","habitat_society":""},{"name":"The Spirit Of Adoration","cr":15,"xp":51200,"alignment":"NG","size":"Large","type":"outsider","subtypes":["extraplanar","good","herald","shapechanger"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["charming (30 ft., DC 24, 1 day)"],"ac":30,"ac_touch":20,"ac_flat_footed":25,"ac_mods":"+6 deflection, +4 Dex, +1 dodge, +10 natural, -1 size","hp":184,"hd":"16d10+96","hdvalue":16,"hp_mods":["fast healing 5"],"fort":17,"ref":20,"will":14,"dr":"10/evil","immunities":["fire","sonic"],"resists":[{"type":"acid","value":30},{"type":"electricity","value":30}],"sr":26,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"ranged":"stunning ray +19 (1d8  plus stun)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bardic magic"},{"type":"bardic performance 40 rounds/day","details":"swift action; countersong, distraction, fascinate, inspire courage +4"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"calm emotions"},{"spell":"cure moderate wounds"},{"spell":"good hope"},{"spell":"teleport","details":"self plus 50 lbs. only"}]}],"strength":18,"dexterity":19,"constitution":22,"intelligence":19,"wisdom":22,"charisma":23,"baseatk":16,"cmb":21,"cmb_special":"+2 vs. sunder","cmd":42,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder","type":"bonus"},{"feat":"Iron Will","type":"bonus"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception)"},{"feat":"Step Up"},{"feat":"Weapon Focus (glaive)"},{"feat":"Wind Stance"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":17},{"skill":"Disguise","value":14},{"skill":"Fly","value":17},{"skill":"Handle Animal","value":14},{"skill":"Heal","value":14},{"skill":"Intimidate","value":17},{"skill":"Knowledge (religion)","value":12},{"skill":"Perception","value":31},{"skill":"Perform (dance)","value":22},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":19},{"skill":"Use Magic Device","value":14}],"languages":["Auran","Celestial","Common","Ignan","Shadowtongue"],"sq":[{"type":"inspiration"},{"type":"unearthly grace"},{"type":"change shape","details":"Small or Medium humanoid; alter self"}],"environments":["any (Nirvana)"],"organizations":["solitary"],"treasure":"triple (+2 dancing glaive)","description_visual":"This heavenly warrior appears to be a work of art come to life. She grips a fearsome glaive that trails brilliant colors.","source":"Inner Sea Gods","special_abilities":[{"type":"Bardic Magic","kind":"Su","details":"Each day, the Spirit can cast any three bard spells of any level and in any combination (caster level 16th)."},{"type":"Inspiration","kind":"Su","details":"The Spirit of Adoration can inspire an intelligent creature by giving it a token of her favor. As long as the creature carries her token, it gains a +4 insight bonus on all Will saving throws, Craft checks, and Perform checks. An inspired bard adds the spirit's Charisma bonus (+6) to his number of bardic performance rounds per day. The spirit retains a link to her token and its carrier as if she had cast the spell status on the carrier. The spirit can end this effect at any time as a free action. The spirit may inspire a number of creatures at a time equal to her Charisma bonus."},{"type":"Stunning Ray","kind":"Su","details":"This ray of brilliant energy has a range of 180 ft. The target takes 1d8 points of damage and is stunned for 1d6 rounds (Will DC 24 reduces this to dazzled). The save DC is Charisma-based."},{"type":"Unearthly Grace","kind":"Su","details":"The spirit adds her Charisma modifier as a racial bonus on all her saving throws, as well as a deflection bonus to her Armor Class."}],"description":"The Spirit of Adoration is a personification of resolute love, whose power lifts the heaviest heart and overcomes all obstacles.\n\nHer true form is that of a 10-foot-tall, angel-winged woman dressed in flowing clothes and bearing a shining steel glaive.","ecology":"","habitat_society":""},{"name":"The Stabbing Beast","cr":15,"xp":51200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar","herald","shapechanger"],"init":16,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"see in darkness"},{"type":"see invisibility"}],"ac":31,"ac_touch":23,"ac_flat_footed":18,"ac_mods":"+12 Dex, +1 dodge, +8 natural","hp":212,"hd":"17d10+119","hdvalue":17,"fort":17,"ref":17,"will":12,"save_mods":"+4 vs. mind-affecting","defensive_abilities":["all-around vision"],"dr":"10/good and magic","immunities":["poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":50}],"ranged":"poison stream +29 touch (blindness 1d4+1 rounds)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"2d6"},{"type":"poison"},{"type":"sudden strike"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"absorbing touch"},{"spell":"alchemical allocation"},{"spell":"charm person"},{"spell":"keen edge"},{"spell":"poison"},{"spell":"true strike"}]},{"frequency":"3/day","spells":[{"spell":"false alibi"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"invisibility"},{"spell":"modify memory"},{"spell":"suggestion"},{"spell":"summon","details":"level 6, 1 fiendish deadfall scorpion 100%"}]}],"strength":16,"dexterity":35,"constitution":24,"intelligence":13,"wisdom":15,"charisma":14,"baseatk":17,"cmb":13,"cmd":28,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Deflect Arrows","type":"bonus"},{"feat":"Dodge"},{"feat":"Greater Feint","type":"bonus"},{"feat":"Improved Feint","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Scorpion Style","type":"bonus"},{"feat":"Spring Attack"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Bluff","value":22},{"skill":"Climb","value":11},{"skill":"Craft (alchemy)","value":13},{"skill":"Knowledge (arcana, nature)","value":10},{"skill":"Knowledge (local)","value":13},{"skill":"Knowledge (planes)","value":12},{"skill":"Knowledge (religion)","value":9},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":32}],"languages":["Abyssal","Celestial","Common","Infernal","Protean","telepathy 100 ft."],"sq":[{"type":"change shape","details":"Huge scorpion or scorpion-tailed human; shapechange"},{"type":"murderer's reward"}],"environments":["any land (Axis)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This towering, scorpion-tailed man stalks with a soundless grace and murderous intent.","source":"Inner Sea Gods","special_abilities":[{"type":"Change Shape","kind":"Su","details":"In its scorpion form, replace or add the following statistics: Size Huge; Init +14; AC 31, touch 21, flat-footed 20 (+10 Dex, +1 dodge, +10 natural); Ref +16; Melee claws +28 (2d6+13 plus bleed and grab), sting +26 (2d6+11 plus bleed and poison); Space 15 ft.; Reach 15 ft.; Special Attacks constrict (2d6+12); Str 32, Dex 31; CMB +30 (+34 grapple); CMD 53 (65 vs. trip); Skills Climb +20, Stealth +24."},{"type":"Murderer's Reward","kind":"Su","details":"If the Stabbing Beast's attack reduces a target to fewer than 0 hit points, it immediately gains 2d6 temporary hit points (or 3d8, if the attack kills the target), but no more than the target's maximum hit points. The temporary hit points last for 1 hour."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 25; frequency 1/round for 6 rounds; effect 1d6 Str; cure 2 consecutive saves."},{"type":"Poison Stream","kind":"Ex","details":"As a ranged attack (or in place of a melee sting attack), the Stabbing Beast can fire a stream of poison up to 180 ft. at an opponent's eyes. The target must succeed at a save against the Stabbing Beast's poison or be blinded for 1d4+1 rounds."},{"type":"Sudden Strike","kind":"Ex","details":"During a surprise round, the herald may act as if it had a full round to act, rather than just one standard action."}],"description":"The Stabbing Beast is the herald of Norgorber, the god of greed, murder, secrets, and poison. It is an incredibly dangerous predator that uses its keen intellect and deadly poison to stalk and kill its prey. Its natural form is that of a huge scorpion, but it can also assume an armored humanoid shape suitable for stealth or interacting with Norgorber's followers. Though its main purpose for coming to Golarion is to kill, it has also been called to aid great thefts and bury terrible secrets.","ecology":"","habitat_society":"","gear":"2 +1 short swords"},{"name":"Toshigami","cr":15,"xp":51200,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["kami","native"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"deathwatch"},{"type":"true seeing"}],"ac":30,"ac_touch":20,"ac_flat_footed":22,"ac_mods":"+6 Dex, +2 dodge, +2 insight, +10 natural","hp":210,"hd":"20d10+100","hdvalue":20,"hp_mods":["fast healing 10"],"fort":11,"ref":23,"will":9,"dr":"10/cold iron and evil","immunities":["bleed","mind-affecting effects","petrification","polymorph"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"+2 quarterstaff +22 (1d6+4 plus touch of ages), +2 quarterstaff +22 (1d6+3 plus touch of ages) or touch +22 (touch of ages)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch"},{"spell":"fly"},{"spell":"foresight"},{"spell":"haste"},{"spell":"speak with plants"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"cure moderate wounds"},{"spell":"tree shape","details":"cherry tree only"},{"spell":"tree stride","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"finger of death"},{"spell":"time stop"},{"spell":"waves of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"greater restoration"},{"spell":"slow"}]}],"strength":15,"dexterity":22,"constitution":20,"intelligence":15,"wisdom":14,"charisma":25,"baseatk":20,"cmb":11,"cmd":27,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Greater Two-Weapon Fighting"},{"feat":"Improved Initiative"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (quarterstaff)"}],"skills":[{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":30},{"skill":"Fly","value":20},{"skill":"Heal","value":25},{"skill":"Knowledge (nature)","value":25},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":29},{"skill":"Survival","value":25}],"languages":["Common","speak with plants","telepathy 100 ft."],"sq":[{"type":"merge with ward"},{"type":"ward","details":"cherry tree"}],"environments":["any land"],"organizations":["solitary"],"treasure":"standard (+2 quarterstaff)","description_visual":"This strangely beautiful old woman is composed completely of blossoms, bark, and antlerlike branches.","group":"Kami","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Touch of Ages","kind":"Su","details":"When a toshigami hits a target with a touch attack or any melee weapon, the target must succeed at a DC 27 Fortitude save to avoid being magically aged. When a toshigami strikes a foe, it must decide whether it wishes to physically increase the target's age or mentally reduce the target's age. If it increases the target's physical age, the target takes 1 point of Strength, Dexterity, and Constitution drain. If it decreases the target's mental age, the target takes 1 point of Intelligence, Wisdom, and Charisma drain. Combined with the toshigami's numerous attacks, this can quickly devastate a target, but once a target succeeds at its saving throw against the touch of ages, it can no longer be affected by this ability for 1 round. This is a magical aging effect, but doesn't actually alter the victim's true age-it merely simulates the creeping effect of age on the flesh or the reversion to an increasingly infantile state of mind. The save DC is Charisma-based."}],"description":"Toshigami, known also as blossom kami, are associated with cherry trees-particularly those that grow in inhabited areas. Often, long after a city has fallen to ruin, these kami guardians are all that remain to remember the lost city's glory. In this way, the toshigami are also associated with the passing of time.\n\nToshigami rarely show themselves except to those in dire need or who are harming their trees. Still, they have a fascination with mortals, and have even been known to form romantic relationships with them on occasion. A toshigami is 5 ft. tall and weighs 100 pounds.","ecology":"","habitat_society":""},{"name":"Ugash-iram","cr":15,"xp":51200,"alignment":"NE","size":"Colossal","type":"magical beast","subtypes":["aquatic"],"init":8,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"see in darkness"}],"ac":28,"ac_touch":6,"ac_flat_footed":24,"ac_mods":"+4 Dex, +22 natural, -8 size","hp":229,"hd":"17d10+136","hdvalue":17,"fort":18,"ref":14,"will":10,"dr":"10/cold iron","resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"speed":[{"type":"land","speed":5},{"type":"swim","speed":60}],"speed_mod":"jet (320 ft.)","melee":"tentacles +20 (6d6+11 plus grab)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"savage bite","details":"+20 melee, 4d8+11/18-20 plus poison"},{"type":"unholy blood"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"disfiguring touch"}]},{"frequency":"1/day","spells":[{"spell":"dominate monster"},{"spell":"rage"}]},{"frequency":"3/day","spells":[{"spell":"bestow curse"},{"spell":"freedom of movement"},{"spell":"protection from energy"}]}],"strength":32,"dexterity":19,"constitution":26,"intelligence":13,"wisdom":20,"charisma":16,"baseatk":17,"cmb":36,"cmb_special":"+4 vs. grapple","cmd":50,"cmd_special":"can't be tripped","feats":[{"feat":"Cleave"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Deadly Finish"},{"feat":"Greater Disarm"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Stand Still"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Knowledge (geography)","value":10},{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":-8},{"skill":"Swim","value":23}],"languages":["Abyssal","Aquan","Common","telepathy 100 ft."],"treasure":"none","description_visual":"This immense creature resembles a horrific, twelve-armed squid. Its emerald eyes burn with a terrifying malignance, and the thing has a fanged maw where its beak should be.","source":"AP 60","special_abilities":[{"type":"Poison","kind":"Ex","details":"Savage bite-injury; save Fort DC 26; frequency 1/round for 6 rounds; effect 1d6 Str; cure 2 consecutive saves."}],"description":"South of Jalmeray, deep in the Yogisa Trench in the middle of the Obari Ocean, the terrifying gutaki known as Ugash-Iram lords over the underwater city of Achom. Ugash-Iram and its lesser kin practice foul rites and perform horrible rituals to honor their patron deity, Dagon, amid the city's strange and twisted spires, which rise out of a dark fissure in the seabed like claws climbing toward the surface. Crackling eruptions of magical energy brief ly illuminate the city in flashes of light, but it is otherwise as dark and lightless as the souls of its foul inhabitants.\n\nBecause of its isolation in the deepest waters of the Obari Ocean, few surface-dwellers know of Ugash- Iram's existence, though those fisherfolk and sailors who've heard tales of the mighty being know to fear it. Locathah sages place the indomitable gutaki's age at over 3,000 years old, and dwellers in the underwater regions surrounding Achom have long loathed and feared Ugash-Iram, whose legions of devotees have spelled the ruin of countless aquatic cities. Ugash-Iram itself is responsible for destroying a dozen massive underwater cities in the past millennium, and the scattered ruins that lie around the Yogisa Trench serve as testament to its power.\n\nThose aquatic creatures Ugash-Iram doesn't outright annihilate are captured and integrated into Achom either as members of the slave caste or as converted devotees to Dagon. Entire tribes of sahuagin, adaros, and iku-tursos have united under the banner of Ugash-Iram and its gutaki kin in Achom, and the underwater metropolis bulges at the borders with the thousands of evil inhabitants who make their home there. These inhabitants raid for Ugash-Iram and populate its city, protecting Achom and performing all kinds of menial tasks for their overlord. With these minions, Ugash-Iram's deadly reach extends all the way to the surface of the Obari Ocean and even the nearby shores of Geb, Jalmeray, and Qadira.\n\nIsolated in its flooded metropolis beneath the sea, Ugash-Iram has plenty of resources, a generous life span, and thousands of minions at its disposal, making it a formidable foe for any who would seek to stop the despotic gutaki before its inf luence spreads even further.\n\nInfamous Deeds\n\nThe legends of Ugash-Iram remain shrouded in mystery, since few aquatic humanoids have seen the monster, and fewer still have lived to tell the tale. Some claim that the gutaki gained its power by devouring other gutaki, gaining greater power and its array of 12 tentacles.\n\nOne especially strange tale claims Ugash-Iram once captured a great kraken and imprisoned it deep in the gaping Yogisa Trench. Ugash-Iram is said to keep the behemoth perpetually on the brink of death-the gutaki and its minions carefully torture the kraken and subject it to grotesque experiments and disfiguring transformations. Just as gutaki were supposedly born when Dagon defeated the great kraken Kaktora, Ugash-Iram hopes that by subjecting its captured kraken to cruel experiments, it can create its own race of 12-tentacled followers.\n\nWhile ships crossing the middle of the Obari Ocean face all manner of risks, perhaps the worst is capture by Ugash-Iram's minions. Records tell of a combined effort by Ugash-Iram's adaro and sahuagin soldiers to capture a diplomatic fleet from Vudra some years ago. A dozen lucky sailors perished during the raid; the aquatic horrors captured everyone else, smearing them with a magical jelly that allowed them to breathe underwater and dragging them to Achom for torture, experimentation, and eventual sacrifice to their lord Dagon.\n\nAdventure Hooks\n\nTracking Ugash-Iram down isn't a task for the faint of heart, and those who do manage to find the vile underwater metropolis of Achom would do well to stay away. Despite the danger, adventurers might find any number of reasons to explore the foul settlement and face its cruel inhabitants.\n\n• A tribe of adaro aligned with Ugash-Iram of Achom threatens Vudrani vessels bound for Jalmeray. At risk of losing their precious cargo, merchants send word to ports along the Obari Ocean's shores, searching for a group to deal with the adaro threat and determine their true motives.\n\n• Tired of living in fear of Ugash-Iram, locathah, merfolk, cecaelias, and other non-evil aquatic creatures recently formed a congress to address the gutaki's tyranny. Legends tell of a magical device of unknown origin lost within the Obari Ocean south of Stonespire Island. Thought to be capable of blocking out mental domination-among other powers-this device would prove a great weapon in the fight against Ugash-Iram and the other denizens of Achom. The aquatic council has put out a great bounty for retrieval of the item.","ecology":"","habitat_society":""},{"name":"Ulkreth","cr":15,"xp":51200,"alignment":"CE","size":"Gargantuan","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":30,"ac_touch":6,"ac_flat_footed":30,"ac_mods":"+24 natural, -4 size","hp":229,"hd":"17d10+136","hdvalue":17,"fort":18,"ref":5,"will":12,"defensive_abilities":["rock catching"],"dr":"10/cold iron and good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"fly","speed":50,"maneuverability":"clumsy"}],"melee":"gore +23 (2d8+10 plus 1d6 piercing), 4 slams +24 (2d6+10/19-20 plus 1d6 piercing)","ranged":"4 rocks +14 (3d6+10)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"boulder barrage"},{"type":"ground pounder"},{"type":"punch through"},{"type":"rend","details":"2 slams, 6d6+15"},{"type":"rock throwing","details":"120 ft."},{"type":"trample","details":"3d6+10, DC 28"},{"type":"wrecker"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"shatter"}]},{"frequency":"1/day","spells":[{"spell":"earthquake"},{"spell":"summon","details":"level 5, 1 ulkreth or 1 omox 40%"}]},{"frequency":"3/day","spells":[{"spell":"move earth"}]}],"strength":30,"dexterity":11,"constitution":26,"intelligence":7,"wisdom":14,"charisma":15,"baseatk":17,"cmb":31,"cmb_special":"+4 vs. overrun, +4 vs. sunder","cmd":43,"cmd_special":"+2 vs. overrun, +2 vs. sunder","feats":[{"feat":"Charge Through"},{"feat":"Greater Overrun"},{"feat":"Greater Sunder"},{"feat":"Improved Critical (slams)"},{"feat":"Improved Overrun"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Sundering Strike"},{"feat":"Weapon Focus (slams)"}],"skills":[{"skill":"Climb","value":28},{"skill":"Intimidate","value":22},{"skill":"Knowledge (engineering)","value":18},{"skill":"Perception","value":30},{"skill":"Swim","value":23}],"languages":["Abyssal","Celestial","Draconic"],"environments":["any (Abyss)"],"organizations":["solitary","crew (2-4 ulkreths)"],"treasure":"standard","description_visual":"This towering monstrosity is clad in cracked boulders, jagged shards of rock, spars of crooked metal, and shredded steel. Four immense arms end in rocky fists, and bony wings protrude from its back.","group":"Demon","source":"AP 73","special_abilities":[{"type":"Boulder Barrage","kind":"Ex","details":"An ulkreth can hurl up to four rocks as a full-round action or two rocks as a standard action. If rocks are available (as when the ulkreth uses its ground pounder ability to create rubble) it can pick up a single rock as a swift action, two rocks as a move action, or four rocks as a full-round action. If an ulkreth has a rock in each hand, it cannot use its rock catching ability."},{"type":"Ground Pounder","kind":"Ex","details":"As a standard action, an ulkreth can strike the ground with its powerful fists, turning the area within a 10-foot radius into dense rubble. Any creatures in this area at the time must succeed at a DC 26 Reflex save or fall prone. An ulkreth's movement isn't slowed by the rubble it creates."},{"type":"Punch Through","kind":"Ex","details":"An ulkreth can use a full-attack action to make its gore and slam attacks against the same opponent. The ulkreth then totals the damage from all hits before applying any damage reduction or hardness."},{"type":"Wrecker","kind":"Su","details":"An ulkreth's rend special attack deals double damage to objects."}],"description":"Ulkreths are among the mightiest servants of the demon lord Xoveron, the Horned Prince of gargoyles and lord of ruination. They exist solely to destroy, carrying out his will of devastation to cities and civilization throughout the planes, tearing down monuments and buildings in the name of their unholy patron. Ulkreths are 25 ft. tall and weigh 10 tons.\n\nEcology\n\nUlkreth demons form from the souls of mortals who spread wanton destruction and vandalism, burning and tearing down what others have labored long to build up. Small-scale vandals don't earn damnation for simple graffiti and petty breakage; ulkreths arise from those who devoted their lives to bringing ruin forge their own chain of condemnation with every new act of malicious deconstruction. Some do so by targeting grand works of art, stately monuments, cathedrals, libraries, and historical edifices, destroying not just physical structures but also the artistic and cultural legacy of their own people, or of other cultures living among them. These targets are singled out for defacement as a sign of the vandal's hate. The pinnacle of vandalism, however, is attained by those who not only cause damage to property but also murder via their sabotage-collapsing mines and trapping miners to die choking in the dark; breaching dams and dikes to unleash deadly floodwaters that wreak devastation; or bombing, burning, or otherwise destroying homes, businesses, and other gathering places. Whether done as an anarchic political statement, for revenge upon those who owned the buildings, or for pure psychotic joy at watching the world crumble, these are the blackest-hearted vandals of all.\n\nThe level of destruction perpetrated by mortals in life is important to their lord Xoveron because while his will is bent on the ruination of every civilization, tearing down the literal and figurative structures that hold society together, he is still only a minor demon lord. His power is insufficient to endow every servant with great abilities. Lesser vandals simply don't rate a major investment of his lordly power, and if made into demons at all, may be consigned to eternity as mere dretches, or as fiendish gargoyles rather than actual demons. It is only those whose acts of destruction are truly heinous that inspire him to transform them into ulkreths.\n\nUlkreth demons are unusual, however, in that they can also be formed not from one soul but from many, especially in the case of gangs that once worked together as mortals in their acts of destruction. These joint-souled ulkreths are, if anything, even more savage and destructive than their fellows, as the different soul fragments bound together struggle for mastery, trying to show their dominance by wreaking greater mayhem than their rivals.\n\nUlkreths don't need to eat or drink, but they enjoy chewing and swallowing powdered stone and shattered glass, twisted metal and splintered wood. They consume the detritus of their destruction as a ritual of satisfaction after their rampages. Some say they gain sustenance from these shattered remains and claim that if ulkreths are prevented from destroying for too long, they can actually waste away and die of starvation, though planar scholars know that outsiders don't need to eat to live. Ulkreths cannot reproduce biologically and are propagated only by the transformation of new souls into ulkreths.\n\nHabitat & Society\n\nMost ulkreths inhabit the endless ruins of Ghahazi, the hearth of their master Xoveron. There they tend groves of fiendish treants that wait amidst the ruins, crumbling foundation stones with their defiled roots even as they stand ready to batter and smash at the ulkreths' command. Flights of fiendish gargoyles wheel constantly overhead, making aeries of the shattered spires of the Horned Prince's city and flocking ahead of the ulkreths when they march. Xoveron often barters the service of his ulkreths with other demon lords or their generals, especially in siege situations where demonic teleportation is of no avail and defenses must be breached with naked strength. Ulkreths may be kept back as artillery, but they chafe under efforts to suppress their urges to sunder and smash and have often been known to abandon their orders and wade directly into a fray or smash down gates and walls with their bare fists.\n\nOn the Material Plane, the cultists of Xoveron and his gargoyle minions stand sentinel against the encroachment of civilization, ready to foil its ambitious reach towards eternity. When his minions report cities growing too great, too lovely, or too proud, Xoveron tempts mortals with a gluttonous hunger for power and a jealous pride and rage toward their fellows that drives them to call forth a ulkreth demon. Mortal gargoyles can sense the presence of one of their master's favored servants and flock to its side to swoop hooting and screeching overhead as the wrecker commences a reign of terror. Of course, ulkreths are notoriously indiscriminate about their destruction, and those summoning them must be very careful not to become casualties of the ulkreth's rampage.","ecology":"Ulkreth demons form from the souls of mortals who spread wanton destruction and vandalism, burning and tearing down what others have labored long to build up. Small-scale vandals don't earn damnation for simple graffiti and petty breakage; ulkreths arise from those who devoted their lives to bringing ruin forge their own chain of condemnation with every new act of malicious deconstruction. Some do so by targeting grand works of art, stately monuments, cathedrals, libraries, and historical edifices, destroying not just physical structures but also the artistic and cultural legacy of their own people, or of other cultures living among them. These targets are singled out for defacement as a sign of the vandal's hate. The pinnacle of vandalism, however, is attained by those who not only cause damage to property but also murder via their sabotage-collapsing mines and trapping miners to die choking in the dark; breaching dams and dikes to unleash deadly floodwaters that wreak devastation; or bombing, burning, or otherwise destroying homes, businesses, and other gathering places. Whether done as an anarchic political statement, for revenge upon those who owned the buildings, or for pure psychotic joy at watching the world crumble, these are the blackest-hearted vandals of all.\n\nThe level of destruction perpetrated by mortals in life is important to their lord Xoveron because while his will is bent on the ruination of every civilization, tearing down the literal and figurative structures that hold society together, he is still only a minor demon lord. His power is insufficient to endow every servant with great abilities. Lesser vandals simply don't rate a major investment of his lordly power, and if made into demons at all, may be consigned to eternity as mere dretches, or as fiendish gargoyles rather than actual demons. It is only those whose acts of destruction are truly heinous that inspire him to transform them into ulkreths.\n\nUlkreth demons are unusual, however, in that they can also be formed not from one soul but from many, especially in the case of gangs that once worked together as mortals in their acts of destruction. These joint-souled ulkreths are, if anything, even more savage and destructive than their fellows, as the different soul fragments bound together struggle for mastery, trying to show their dominance by wreaking greater mayhem than their rivals.\n\nUlkreths don't need to eat or drink, but they enjoy chewing and swallowing powdered stone and shattered glass, twisted metal and splintered wood. They consume the detritus of their destruction as a ritual of satisfaction after their rampages. Some say they gain sustenance from these shattered remains and claim that if ulkreths are prevented from destroying for too long, they can actually waste away and die of starvation, though planar scholars know that outsiders don't need to eat to live. Ulkreths cannot reproduce biologically and are propagated only by the transformation of new souls into ulkreths.","habitat_society":"Most ulkreths inhabit the endless ruins of Ghahazi, the hearth of their master Xoveron. There they tend groves of fiendish treants that wait amidst the ruins, crumbling foundation stones with their defiled roots even as they stand ready to batter and smash at the ulkreths' command. Flights of fiendish gargoyles wheel constantly overhead, making aeries of the shattered spires of the Horned Prince's city and flocking ahead of the ulkreths when they march. Xoveron often barters the service of his ulkreths with other demon lords or their generals, especially in siege situations where demonic teleportation is of no avail and defenses must be breached with naked strength. Ulkreths may be kept back as artillery, but they chafe under efforts to suppress their urges to sunder and smash and have often been known to abandon their orders and wade directly into a fray or smash down gates and walls with their bare fists.\n\nOn the Material Plane, the cultists of Xoveron and his gargoyle minions stand sentinel against the encroachment of civilization, ready to foil its ambitious reach towards eternity. When his minions report cities growing too great, too lovely, or too proud, Xoveron tempts mortals with a gluttonous hunger for power and a jealous pride and rage toward their fellows that drives them to call forth a ulkreth demon. Mortal gargoyles can sense the presence of one of their master's favored servants and flock to its side to swoop hooting and screeching overhead as the wrecker commences a reign of terror. Of course, ulkreths are notoriously indiscriminate about their destruction, and those summoning them must be very careful not to become casualties of the ulkreth's rampage."},{"name":"Very Old Black Dragon","cr":15,"xp":51200,"alignment":"CE","size":"Huge","type":"dragon","subtypes":["water"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (270 ft., DC 23)"],"ac":35,"ac_touch":8,"ac_flat_footed":35,"ac_mods":"+27 natural, -2 size","hp":250,"hd":"20d12+120","hdvalue":20,"fort":18,"ref":12,"will":16,"dr":"15/magic","immunities":["acid","paralysis","sleep"],"sr":26,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"swim","speed":60}],"melee":"bite +29 (2d8+15 plus 2d6 acid), 2 claws +28 (2d6+10), 2 wings +26 (1d8+5), tail slap +26 (2d6+15)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"acidic bite"},{"type":"breath weapon","details":"100-ft. line, DC 26, 18d6 acid"},{"type":"corrupt water"},{"type":"crush","details":"DC 26, 2d8+15"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness","details":"90-ft. radius"},{"spell":"plant growth"}]}],"spellsknown_caster_level":9,"spellsknown_concentration":15,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"},{"spell":"dimension door"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"heroism"},{"spell":"hold person"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":31,"dexterity":10,"constitution":23,"intelligence":16,"wisdom":19,"charisma":16,"baseatk":20,"cmb":32,"cmd":42,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Greater Vital Strike"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":15},{"skill":"Handle Animal","value":23},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":26},{"skill":"Knowledge (history)","value":26},{"skill":"Perception","value":31},{"skill":"Spellcraft","value":26},{"skill":"Stealth","value":21},{"skill":"Swim","value":41}],"languages":["Common","Draconic","Giant","Orc"],"sq":[{"type":"speak with reptiles"},{"type":"swamp stride"},{"type":"water breathing"}],"environments":["warm marshes"],"organizations":["solitary"],"treasure":"triple","description_visual":"Hissing green acid drips from the fanged maw of this black-scaled, horned dragon.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Acidic Bite","kind":"Su","details":"At old age, a black dragon's bite deals an additional 2d6 points of acid damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older black dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC equal to the dragon's frightful presence) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is equal to that of the dragon's frightful presence."},{"type":"Crush","kind":"Ex","details":"A flying or jumping Huge or larger dragon can land on foes as a standard action, using its whole body to crush them. Crush attacks are effective only against opponents three or more size categories smaller than the dragon. A crush attack affects as many creatures as fit in the dragon's space. Creatures in the affected area must succeed on a Reflex save (DC equal to that of the dragon's breath weapon) or be pinned, automatically taking bludgeoning damage during the next round unless the dragon moves off them. If the dragon chooses to maintain the pin, it must succeed at a combat maneuver check as normal. Pinned foes take damage from the crush each round if they don't escape. A crush attack deals the indicated damage plus 1-1/2 times the dragon's Strength bonus."},{"type":"Speak with Reptiles","kind":"Sp","details":"A young or older black dragon gains the constant spell-like ability to speak with reptiles. This functions as speak with animals, but only with reptilian animals."},{"type":"Swamp Stride","kind":"Ex","details":"A very young or older black dragon can move through bogs and quicksand without penalty at its normal speed."},{"type":"Water Breathing","kind":"Ex","details":"A black dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."}],"description":"Lording over the darkest swamps and marshes, black dragons are the undisputed masters of their domain, ruling through cruelty and intimidation. Those who dwell within a black dragon's reach live in fear. Black dragons tend to make their lairs in remote parts of the swamp, preferably in caves at the bottom of dark and fetid pools. Inside, they pile up their filthy treasure and sleep amid the roots and muck. Black dragons prefer their food a bit rotten and will often allow a meal to sit in a pool for days before consuming it. Black dragons prefer treasures that don't rot or decay, making their hoard, full of coins, gemstones, jewelry, and other objects made from stone or metal.","ecology":"","habitat_society":""},{"name":"Very Old Brass Dragon","cr":15,"xp":51200,"alignment":"CG","size":"Huge","type":"dragon","subtypes":["fire"],"init":4,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"dragon senses"}],"auras":["fire (5 ft., 1d6 fire)","frightful presence (270 ft., DC 24)"],"ac":35,"ac_touch":8,"ac_flat_footed":35,"ac_mods":"+27 natural, -2 size","hp":250,"hd":"20d12+120","hdvalue":20,"fort":18,"ref":12,"will":16,"dr":"15/magic","immunities":["fire","paralysis","sleep"],"sr":26,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"burrow","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +28 (2d8+15), 2 claws +28 (2d6+10), 2 wings +26 (1d8+5), tail slap +26 (2d6+15)","space":"15 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100-ft. line, DC 26, 18d4 fire"},{"type":"crush","details":"small creatures, DC 26, 2d8+15"},{"type":"desert wind"},{"type":"sleep breath"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control winds"},{"spell":"endure elements"},{"spell":"speak with animals"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":13,"spellsknown_concentration":19,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"forceful hand"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"dominate person"},{"spell":"mirage arcana"},{"spell":"prying eyes"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"charm monster"},{"spell":"confusion"},{"spell":"dimensional anchor"},{"spell":"locate creature"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"displacement"},{"spell":"heroism"},{"spell":"hold person"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"alter self"},{"spell":"detect thoughts"},{"spell":"locate object"},{"spell":"resist energy"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"protection from evil"},{"spell":"shield"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":31,"dexterity":10,"constitution":23,"intelligence":18,"wisdom":19,"charisma":18,"baseatk":20,"cmb":32,"cmd":42,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Greater Spell Focus (enchantment)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Spell Focus (enchantment)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":27},{"skill":"Fly","value":15},{"skill":"Heal","value":27},{"skill":"Knowledge (local)","value":27},{"skill":"Linguistics","value":27},{"skill":"Perception","value":31},{"skill":"Sense Motive","value":31},{"skill":"Spellcraft","value":27},{"skill":"Survival","value":27}],"languages":["Common","Draconic","any 22 more"],"sq":[{"type":"move sand"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crest of horns sweeps back from the head of this dragon, leading to a long neck and serpentine brass body.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Desert Wind","kind":"Su","details":"A juvenile or older brass dragon can call up the desert wind to serve him. This functions as gust of wind, but any creature in its path must make a Fortitude save (DC 26) or be blinded for 1d4 rounds by the sand."},{"type":"Fire Aura","kind":"Su","details":"An old or older brass dragon is surrounded by an aura of intense heat. All creatures within 5 ft. of the dragon take 1d6 points of fire damage at the beginning of the dragon's turn. An ancient brass dragon's aura extends to 10 ft. A great wyrm's damage increases to 2d6. A brass dragon can suppress or activate this aura at will as a free action."},{"type":"Move Sand","kind":"Su","details":"A young or older brass dragon can move sand to excavate ruins or hide treasures. This functions as move earth, but it only affects sand. The dragon uses his HD in place of his caster level for this effect. This is equivalent to a 5th-level spell."},{"type":"Sleep Breath","kind":"Su","details":"Instead of a line of fire, a brass dragon can breathe a 50 ft. cone of sleep gas. Creatures within the cone must succeed on a Will save or fall asleep for 1d6+9 rounds."}],"description":"Consummate conversationalists, brass dragons prefer to talk instead of fight. Brass dragons lair near humanoid settlements, where they can hear the most recent news and gossip.","ecology":"","habitat_society":""},{"name":"Woundwyrm","cr":15,"xp":51200,"alignment":"CE","size":"Huge","type":"dragon","subtypes":["chaotic","evil"],"init":5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":30,"ac_touch":10,"ac_flat_footed":28,"ac_mods":"+1 Dex, +1 dodge, +20 natural, -2 size","hp":225,"hd":"18d12+108","hdvalue":18,"fort":17,"ref":12,"will":12,"dr":"10/good or lawful","immunities":["acid","dragon traits","gaze attacks","illusions","magic paralysis and sleep","poison","polymorph","visual effects"],"sr":26,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30},{"type":"fly","speed":60,"maneuverability":"average"},{"type":"swim","speed":30}],"melee":"bite +26 (2d8+10), 2 claws +26 (2d6+10), tail slap +21 (2d8+5), 2 wings +21 (1d8+5)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100-ft. line, 16d6, Reflex DC 25 for half, usable every 1d4 rounds"},{"type":"entropic breath"},{"type":"maw of the Abyss"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"entropic shield"},{"spell":"freedom of movement"}]},{"frequency":"1/day","spells":[{"spell":"polymorph any object"}]}],"strength":31,"dexterity":13,"constitution":22,"intelligence":14,"wisdom":13,"charisma":20,"baseatk":18,"cmb":30,"cmd":42,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Bluff","value":18},{"skill":"Diplomacy","value":15},{"skill":"Fly","value":18},{"skill":"Intimidate","value":26},{"skill":"Knowledge (planes)","value":23},{"skill":"Perception","value":22},{"skill":"Spellcraft","value":23},{"skill":"Survival","value":22},{"skill":"Swim","value":22}],"languages":["Abyssal","Common","Draconic"],"environments":["any (the Worldwound)"],"organizations":["solitary"],"treasure":"triple","description_visual":"This massive, eyeless draconic creature is covered in purple-hued scales and sharp, spiky protrusions.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Entropic Breath","kind":"Su","details":"Instead of a line of acid, a woundwyrm can exhale a 30-foot cone of acid fog (as the spell) that persists for 1 minute. Any creature that begins its turn within the entropic breath becomes confused (Will DC 25 negates) for as long as it remains within the cloud and for 1d6 rounds thereafter."},{"type":"Maw of the Abyss","kind":"Su","details":"As a full-round action, a woundwyrm can attempt to suck creatures and unattended objects in a 15-foot cone into a vortex in its maw. This acts as a drag combat maneuver (CMB +30) against creatures, and acts as a Strength check with a +10 bonus to break objects. Unattended objects weighing less than 100 pounds are automatically drawn into its maw. Creatures and objects alike take 1d12 points of sonic damage per round within the cone. While using this ability, a woundwyrm cannot speak, use its breath weapon, or make attacks or attacks of opportunity with its bite attack."}],"description":"Woundwyrms are ferocious predators native to the corrupted landscape of the Worldwound. They are equally at home in sea and sky, above the ground and below it. Oozing deliquescence seeps from between their cracked, rocky scales, and a constant fume of rainbow hues drifts out of their gullets, save when they inhale and ingest the very substance of disintegrating reality.","ecology":"","habitat_society":""},{"name":"Xacarba","cr":15,"xp":51200,"alignment":"CE","size":"Gargantuan","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":9,"senses":[{"type":"arcane sight"},{"type":"darkvision","modifier":"120 ft."},{"type":"detect good"},{"type":"low-light vision"},{"type":"scent"},{"type":"true seeing"}],"ac":31,"ac_touch":12,"ac_flat_footed":25,"ac_mods":"+5 Dex, +1 dodge, +19 natural, -4 size","hp":210,"hd":"20d10+100","hdvalue":20,"fort":17,"ref":13,"will":20,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +25 (3d8+9 plus poison), 3 tail slaps +20 (2d8+4 plus grab)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"2d6+9"},{"type":"redirect spell"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"arcane sight"},{"spell":"detect good"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"detect thoughts"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"invisibility"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 5, 1 hezrou or 1d4 succubi, 50%"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"mass suggestion"},{"spell":"scrying"},{"spell":"symbol of pain"},{"spell":"touch of idiocy"},{"spell":"vision"}]}],"strength":29,"dexterity":21,"constitution":21,"intelligence":26,"wisdom":22,"charisma":24,"baseatk":20,"cmb":33,"cmb_special":"+4 vs. grapple","cmd":49,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":25,"special":"+29 jump"},{"skill":"Bluff","value":30},{"skill":"Climb","value":17},{"skill":"Diplomacy","value":27},{"skill":"Disguise","value":27},{"skill":"Intimidate","value":27},{"skill":"Knowledge (arcana)","value":31},{"skill":"Knowledge (any two)","value":31},{"skill":"Linguistics","value":28},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":31},{"skill":"Stealth","value":16},{"skill":"Use Magic Device","value":27}],"languages":["Abyssal","Common","Draconic","telepathy 100 ft."],"sq":[{"type":"change shape","details":"any humanoid as a swift action, but always retains one serpentine trait that negates the bonus to Disguise checks; alter self"}],"environments":["any land (Abyss)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This towering, three-tailed, six-eyed beast seems like three rune-backed serpents partially melded together into one body.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 25; frequency 1/ round for 6 rounds; effect one chosen by the xacarba from three options; cure 2 consecutive saves. The save DC is Constitution-based. Fiendish Bile: effect 1d4 Str damage (good-aligned creatures also take 2d8 points of damage). Mysterious Blood: effect 1d4 Dex and 1d4 Wis damage plus confusion for 1 round. Vile Disjunction: effect targeted greater dispel magic (CL 18th) on the creature."},{"type":"Redirect Spell","kind":"Su","details":"Any creature that attempts to cast a spell within 30 ft. of a xacarba must cast the spell defensively. If the caster fails the concentration check to do so (or if the caster opts to not cast defensively), the xacarba can choose the target of the spell as an immediate action. The new target must be a legal target-if there's no legal alternative target to choose from, this ability cannot be used."}],"description":"Fiends hailing from the darkest reaches of the Abyss, xacarbas are manipulation and destruction intertwined. With their infamous ability to redirect spells, these serpentine goliaths wreak havoc on the mind as well as the body, turning allies against one another and reveling in the destruction doing so produces.","ecology":"","habitat_society":""},{"name":"Yethazmari","cr":15,"xp":51200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar","herald"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":32,"ac_touch":14,"ac_flat_footed":27,"ac_mods":"+5 Dex, +18 natural, -1 size","hp":207,"hd":"18d10+108","hdvalue":18,"fort":17,"ref":11,"will":17,"defensive_abilities":["soul scream"],"dr":"15/good","immunities":["fire"],"sr":26,"speed":[{"type":"land","speed":50},{"type":"fly","speed":100,"maneuverability":"good"}],"melee":"bite +25 (6d6+8/19-20), bite +25 (3d6+8/19-20 plus poison)","ranged":"poison gout +22 touch (6d10 acid plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bay"},{"type":"breath weapon","details":"30-ft. cone, 12d10 fire and see below, Reflex DC 25 half, usable every 1d4 rounds"},{"type":"poison"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"blindness/deafness"},{"spell":"locate creature"},{"spell":"rage"},{"spell":"veil"}]},{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"unhallow"}]},{"frequency":"3/day","spells":[{"spell":"baleful polymorph"},{"spell":"feeblemind"},{"spell":"greater dispel magic"},{"spell":"plane shift","details":"self and willing targets only"},{"spell":"summon","details":"level 4, 1d3 yeth hounds 100%"}]}],"strength":26,"dexterity":20,"constitution":22,"intelligence":17,"wisdom":23,"charisma":22,"baseatk":18,"cmb":27,"cmb_special":"+2 vs. bull rush or drag","cmd":42,"cmd_special":"+2 vs. bull rush or drag, +4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Drag"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":26},{"skill":"Bluff","value":27},{"skill":"Climb","value":17},{"skill":"Fly","value":7},{"skill":"Intimidate","value":27},{"skill":"Knowledge (planes)","value":24},{"skill":"Knowledge (religion)","value":15},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":22},{"skill":"Survival","value":27}],"languages":["Abyssal","Common","Infernal"],"environments":["any (Abyss)"],"organizations":["solitary"],"treasure":"none","description_visual":"This starving, jackal-like monstrosity has a fanged snake where its tail should be, tattered wings, and smoking eye sockets.","source":"Inner Sea Gods","special_abilities":[{"type":"Bay","kind":"Su","details":"When the Yethazmari howls or barks, each creature within a 300-foot-radius spread must succeed at a DC 25 Will save or be panicked for 2d4 rounds. This is a sonic mindaffecting fear effect. Evil outsiders are immune to this ability. Whether or not it succeeds at its save, a creature in the area is immune to the Yethazmari's bay for 24 hours. The save DC is Charisma-based."},{"type":"Breath Weapon","kind":"Su","details":"The Yethazmari's breath weapon is a jet of smoke. Any nonchaotic creature that takes damage from this breath weapon must succeed at a DC 25 Will save or be confused for 1d6 rounds. The save DC is Constitution-based."},{"type":"Soul Scream","kind":"Su","details":"Anytime the Yethazmari takes piercing or slashing damage, its wounds create a terrifying cacophony equivalent to its bay ability. Creatures within 10 ft. of it take a -4 penalty on their saves against this effect."},{"type":"Poison","kind":"Ex","details":"Contact or bite-injury; save Fort DC 25; frequency 1/round for 4 rounds; effect 1d6 Str; cure 2 consecutive saves."}],"description":"Having witnessed the most profane atrocities committed by the Mother of Monsters, the eyes of Lamashtu's herald-the Yethazmari-burned to smoldering coals. Now this ancient monstrosity, often said to be Lamashtu's favored offspring, sees only worlds undone and endless ruinous visions of reality rent by Lamashtu's claws. The Yethazmari stands 14 ft. tall and weighs over 1,600 pounds.","ecology":"","habitat_society":""},{"name":"Ypotryll","cr":15,"xp":51200,"alignment":"N","size":"Huge","type":"magical beast","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"-1 Dex, +22 natural, -2 size","hp":253,"hd":"22d10+132","hdvalue":22,"fort":21,"ref":12,"will":9,"save_mods":"+6 vs. charms and compulsions","dr":"5/-","speed":[{"type":"land","speed":60}],"melee":"gore +31 (4d8+16 plus push), 2 hooves +29 (2d8+11), tail slap +29 (2d6+5 plus push)","space":"10 ft.","reach":"15 ft. (15 ft. with tail slap)","special_attacks":[{"type":"destructive charge"},{"type":"push","details":"gore, tail slap, 10 ft."},{"type":"thundering path"},{"type":"trample","details":"2d8+16"},{"type":"unstoppable force"}],"strength":32,"dexterity":9,"constitution":21,"intelligence":2,"wisdom":10,"charisma":7,"baseatk":22,"cmb":35,"cmb_special":"+2 vs. bull rush, +4 vs. overrun","cmd":44,"cmd_special":"+2 vs. bull rush, +2 vs. overrun","feats":[{"feat":"Charge Through"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Greater Overrun"},{"feat":"Improved Bull Rush"},{"feat":"Improved Overrun"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+18 when jumping"},{"skill":"Perception","value":12},{"skill":"Survival","value":4},{"skill":"Swim","value":23}],"sq":[{"type":"bloody-minded"}],"environments":["any coasts","any hills","temperate marshes"],"organizations":["solitary","pair","herd (3-16)"],"treasure":"none","description_visual":"This ugly creature's porcine head features multiple horns and tusks. Its muscular body ripples with raw power.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Bloody-Minded","kind":"Ex","details":"A ypotryll isn't easily swayed from its bloody business. It gains a +6 bonus on saves against charm and compulsion effects."},{"type":"Destructive Charge","kind":"Ex","details":"A ypotryll's charge attack ignores up to 1 point of a target object's hardness for each 5 ft. charged."},{"type":"Thundering Path","kind":"Ex","details":"A ypotryll's charge shakes the ground it crosses. The path of its charge is considered difficult terrain until the start of the ypotryll's next turn, and creatures with tremorsense that are within 100 ft. of the end of the ypotryll's charge are blinded for that same amount of time."},{"type":"Unstoppable Force","kind":"Ex","details":"A ypotryll's bonus on a charge attack is +4, and it may add this bonus on overrun combat maneuver checks attempted using Charge Through."}],"description":"A ypotryll may charge over difficult terrain, provided the terrain doesn't cost more than 2 squares to enter. For those unfortunate enough to get in an ypotryll's way, the thundering rhythm of its hooves is the sound of doom. These creatures are pure savagery and destruction incarnate. A bulk of muscle and hate, a charging ypotryll can be slowed by few things. Bodies and viscera are strewed about when this powerful boarlike juggernaut hits a shield wall, and pikes splinter on its armored plates as if they were twigs. Given enough momentum, a charging ypotryll can rip apart a drawbridge or even the crash through a keep's walls. Powerful savage tribes corral these beasts and unleash their carnage on the battlefield. Giants and powerful troll chiefs prize ypotrylls, and spend much time and resources to break them, though ypotrylls' volatile nature ensures such domestication is rare. When it does happen, they make truly frightening steeds. In the wild, ypotrylls spend their time roaming their territory looking for enough food to support their massive bodies. While they prefer meat, these creatures are omnivores and will eat almost anything. Ypotrylls are especially fond of the scraps they can find in the trash heaps of civilized races, which can mean disaster for a settlement.","ecology":"","habitat_society":""},{"name":"Abyss Gigas","cr":16,"xp":76800,"alignment":"CE","size":"Gargantuan","type":"humanoid","subtypes":["chaotic","evil","extraplanar","giant"],"init":5,"senses":[{"type":"blindsight","modifier":"100 ft."}],"ac":31,"ac_touch":7,"ac_flat_footed":30,"ac_mods":"+9 armor, +1 Dex, +15 natural, -4 size","hp":283,"hd":"21d8+189","hdvalue":21,"fort":21,"ref":8,"will":10,"defensive_abilities":["rock catching"],"dr":"3/-, 10/lawful","immunities":["electricity"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10},{"type":"sonic","value":10}],"speed":[{"type":"land","speed":50,"special":"60 ft. without armor"}],"melee":"mwk adamantine warhammer +25 (4d6+19/19-20/x3), bite +19 (2d8+6 plus wrenching spasms)","ranged":"rock +13 (4d6+19)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"rock throwing","details":"160 ft."}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"fear"},{"spell":"mirror image"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"dominate person"},{"spell":"telekinesis"},{"spell":"true seeing"}]}],"strength":37,"dexterity":12,"constitution":28,"intelligence":20,"wisdom":17,"charisma":15,"baseatk":15,"cmb":32,"cmb_special":"+2 vs. bull rush, +4 vs. sunder","cmd":43,"cmd_special":"+2 vs. bull rush and sunder","feats":[{"feat":"Awesome Blow"},{"feat":"Catch Off-Guard"},{"feat":"Combat Reflexes"},{"feat":"Greater Sunder"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (warhammer)"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Stand Still"},{"feat":"Throw Anything"}],"skills":[{"skill":"Climb","value":32},{"skill":"Intimidate","value":26},{"skill":"Knowledge (planes)","value":26},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":24},{"skill":"Stealth","value":5},{"skill":"Survival","value":27}],"languages":["Abyssal","Common","Giant"],"sq":[{"type":"planar empowerment"}],"environments":["any (Abyss)"],"organizations":["solitary","pair","gang (3-7)"],"treasure":"standard (adamantine full plate, adamantine warhammer)","description_visual":"This ebon-skinned monstrosity has a gaping maw with boarlike tusks and a wide nose beneath a furrowed brow that lacks any sort of eyes or visible visual organs. Its corded muscles twist and writhe beneath its smooth, hairless jet hide, giving its frame a gnarled, unbalanced asymmetry. It moves with a loping gait, however, and wears its armor, composed of thick, welded plates, effortlessly.","group":"Abyss","source":"The Witchwar Legacy","special_abilities":[{"type":"Planar Empowerment","kind":"Su","details":"While on the plane of the Abyss, an Abyss gigas gains access to blasphemy (DC 24), cloak of chaos (DC 25), and earthquake (DC 25) as spell-like abilities, each usable once per day. If the gigas ventures onto another plane, it cannot make use of these abilities (though its other spelllike abilities remain available). The save DC for the spell-like abilities is Charisma-based and includes a +5 racial bonus."},{"type":"Wrenching Spasms","kind":"Su","details":"When an Abyss gigas hits an opponent with its bite attack, the opponent must make a DC 29 Fort save or be overcome by wrenching spasms that wrack its body. These spasms cause the victim to be nauseated and deal 1d6 points of damage to Strength and Dexterity due to the painful contortion of bones, muscles, and limbs. The spasms continue for 1d6 hours or until healed with heal, regenerate, or greater restoration. The effects of this ability don't stack, but once a creature has recovered from or been cured of the effect, it can be affected again. Once a creature has made a successful saving throw against this effect, it cannot be affected by the wrenching spasms from that particular gigas for 24 hours. The save DC is Constitution-based."}],"description":"Spawned from titans who took refuge in the rifts of the Abyss, the Abyss gigas roam the wastes between the once mighty titan fortresses. These powerful beings don't typically dwell among their own kind, preferring instead to enslave lesser beings-demons and captured planar travelers-and rule over them as despotic tyrants. Many Abyss gigas serve more powerful demon lords in turn. When more than one of the thankfully rare Abyss gigas live near each other, they exist in a state of perpetual warfare, sending forth wave after wave of their minions in battle. In these situations, only rarely do the gigas masters ever face each other and come to blows, and even then never to the death, as they are aware of the fragile existence of their nearly extinct race. When facing other opponents, however, an Abyss gigas is a fearsome foe, battling to the death to prove the superiority of its ancient line. When encountered on the Material Plane, Abyss gigas are fond of taking control of companies of giants and compelling them to do their bidding, feeling at once both a distant kinship and a sense of domineering superiority. Frost giant cults of Kostchtchie are frequent recipients of this sort of attention. Abyss gigas stand over 50 ft. tall and weigh 25 tons or more, not including the weight of their Abyss-forged armor and weapons of adamantine. Abyss gigas usually favor the weapons of their demonic patrons. For example, followers of Kostchtchie often wield giant warhammers in both hands, servants of Lamashtu carry falchions, and those serving Urxehl use spiked greatclubs.","ecology":"","habitat_society":""},{"name":"Ancient Black Dragon","cr":16,"xp":76800,"alignment":"CE","size":"Huge","type":"dragon","subtypes":["water"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (300 ft., DC 25)"],"ac":38,"ac_touch":8,"ac_flat_footed":38,"ac_mods":"+30 natural, -2 size","hp":297,"hd":"22d12+154","hdvalue":22,"fort":20,"ref":13,"will":18,"dr":"15/magic","immunities":["acid","paralysis","sleep"],"sr":27,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"swim","speed":60}],"melee":"bite +32 (2d8+16 plus 4d6 acid), 2 claws +31 (2d6+11), 2 wings +29 (1d8+5), tail +29 (2d6+16)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"acid pool","details":"50-ft. radius"},{"type":"acidic bite"},{"type":"breath weapon","details":"100-ft. line, DC 28, 20d6 acid"},{"type":"corrupt water"},{"type":"crush"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness","details":"100 ft. radius"},{"spell":"insect plague"},{"spell":"plant growth"}]}],"spellsknown_caster_level":11,"spellsknown_concentration":18,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"cone of cold"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"arcane eye"},{"spell":"black tentacles"},{"spell":"dimension door"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"heroism"},{"spell":"hold person"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"summon swarm"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":33,"dexterity":10,"constitution":25,"intelligence":18,"wisdom":21,"charisma":18,"baseatk":22,"cmb":35,"cmd":45,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Flyby Attack"},{"feat":"Greater Vital Strike"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":17},{"skill":"Handle Animal","value":26},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (history)","value":29},{"skill":"Knowledge (geography)","value":29},{"skill":"Perception","value":34},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":23},{"skill":"Swim","value":44}],"languages":["Common","Draconic","Giant","Goblin","Orc"],"sq":[{"type":"speak with reptiles"},{"type":"swamp stride"},{"type":"water breathing"}],"environments":["warm marshes"],"organizations":["solitary"],"treasure":"triple","description_visual":"Hissing green acid drips from the fanged maw of this blackscaled, horned dragon.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Acid Pool","kind":"Su","details":"An ancient or older black dragon can use its breath weapon to create an acid pool as a standard action. This acid pool has a radius of 5 ft. per age category of the dragon. When an acid pool is created, anyone inside its area takes an amount of damage equal to the dragon's breath weapon (Reflex half). Any creature that starts its turn touching this pool takes damage, but can make a Reflex save for half. Each round, the total damage dice of the pool is halved until the result would be less than 1d6. The acid pool floats on water, and deals damage to anything on the surface."},{"type":"Acidic Bite","kind":"Su","details":"At old age, a black dragon's bite deals an additional 2d6 points of acid damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Charm Reptiles","kind":"Sp","details":"A great wyrm black dragon can use this ability three times per day. It works as a mass charm monster spell that affects only reptilian animals. This ability is the equivalent of an 8th-level spell."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older black dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC equal to the dragon's frightful presence) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is equal to that of the dragon's frightful presence."},{"type":"Speak with Reptiles","kind":"Sp","details":"A young or older black dragon gains the constant spell-like ability to speak with reptiles. This functions as speak with animals, but only with reptilian animals."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A black dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. Juvenile-darkness (radius 10 ft. per age category); Old-plant growth; Ancient-insect plague."},{"type":"Swamp Stride","kind":"Ex","details":"A very young or older black dragon can move through bogs and quicksand without penalty at its normal speed. Hissing green acid drips from the fanged maw of this blackscaled, horned dragon."},{"type":"Water Breathing","kind":"Ex","details":"A black dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged. Age Category S pecial Abilities Caster Level Wyrmling Immunity to acid, water breathing - Very young Swamp stride - Young Speak with reptiles - Juvenile Darkness - Young adult DR 5/magic, spell resistance 1st Adult Corrupt water, frightful presence 3rd Mature adult DR 10/magic 5th Old Acidic bite, plant growth 7th Very old DR 15/magic 9th Ancient Acid pool, insect plague 11th Wyrm DR 20/magic 13th Great wyrm Charm reptiles 15th."}],"description":"Lording over the darkest swamps and marshes, black dragons are the undisputed masters of their domain, ruling through cruelty and intimidation. Those who dwell within a black dragon's reach live in fear. Black dragons tend to make their lairs in remote parts of the swamp, preferably in caves at the bottom of dark and fetid pools. Inside, they pile up their filthy treasure and sleep amid the roots and muck. Black dragons prefer their food a bit rotten and will often allow a meal to sit in a pool for days before consuming it. Black dragons prefer treasures that don't rot or decay, making their hoard, full of coins, gemstones, jewelry, and other objects made from stone or metal.","ecology":"","habitat_society":""},{"name":"Ancient Brass Dragon","cr":16,"xp":76800,"alignment":"CG","size":"Huge","type":"dragon","subtypes":["fire"],"init":4,"senses":[{"type":"dragon senses"}],"auras":["fire (10 ft., 1d6 fire)","frightful presence (300 ft., DC 26)"],"ac":38,"ac_touch":8,"ac_flat_footed":38,"ac_mods":"+30 natural, -2 size","hp":297,"hd":"22d12+154","hdvalue":22,"fort":20,"ref":13,"will":18,"dr":"15/magic","immunities":["fire","paralysis","sleep"],"sr":27,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"burrow","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +31 (2d8+16), 2 claws +31 (2d6+11), 2 wings +29 (1d8+5), tail slap +29 (2d6+16)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"100-ft. line, DC 28, 20d4 fire"},{"type":"crush"},{"type":"desert wind"},{"type":"sandstorm"},{"type":"sleep breath"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control weather"},{"spell":"control winds"},{"spell":"endure elements"},{"spell":"speak with animals"},{"spell":"suggestion"}]}],"spellsknown_caster_level":15,"spellsknown_concentration":22,"spellsknown":[{"spell_level":7,"spell_slots":4,"spells":[{"spell":"greater teleport"},{"spell":"power word blind"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"forceful hand"},{"spell":"geas"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"contact other plane"},{"spell":"dominate person"},{"spell":"mirage arcana"},{"spell":"prying eyes"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"charm monster"},{"spell":"confusion"},{"spell":"dimensional anchor"},{"spell":"locate creature"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"displacement"},{"spell":"heroism"},{"spell":"hold person"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"alter self"},{"spell":"detect thoughts"},{"spell":"locate object"},{"spell":"resist energy"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"protection from evil"},{"spell":"shield"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"dispell magic"},{"spell":"detect poison"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":33,"dexterity":10,"constitution":25,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":22,"cmb":35,"cmd":45,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Greater Spell Focus (enchant)"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Spell Focus (enchant)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":30},{"skill":"Fly","value":17},{"skill":"Heal","value":30},{"skill":"Knowledge (local, history)","value":30},{"skill":"Linguistics","value":30},{"skill":"Perception","value":34},{"skill":"Sense Motive","value":34},{"skill":"Spellcraft","value":30},{"skill":"Survival","value":30}],"languages":["Common","Draconic","any 22"],"sq":[{"type":"move sand"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crest of horns sweeps back from the head of this dragon, leading to a long neck and serpentine brass body.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Desert Wind","kind":"Su","details":"A juvenile or older brass dragon can call up the desert wind to serve him. This functions as gust of wind, but any creature in its path must make a Fortitude save or be blinded for 1d4 rounds by the sand. The save DC for this effect is equal to the dragon's breath weapon DC."},{"type":"Fire Aura","kind":"Su","details":"An old or older brass dragon is surrounded by an aura of intense heat. All creatures within 5 ft. of the dragon take 1d6 points of fire damage at the beginning of the dragon's turn. An ancient brass dragon's aura extends to 10 ft. A great wyrm's damage increases to 2d6. A brass dragon can suppress or activate this aura at will as a free action."},{"type":"Move Sand","kind":"Sp","details":"A young or older brass dragon can move sand to excavate ruins or hide treasures. This functions as move earth, but it only affects sand. The dragon uses his HD in place of his caster level for this effect. This is equivalent to a 5th-level spell."},{"type":"Sandstorm","kind":"Su","details":"An ancient or older brass dragon can create a powerful sandstorm once per day as a full-round action. This storm has a radius of 1 mile and lasts for 1 minute per age category of the dragon. This functions as a sandstorm, except that it is also accompanied by windstorm-level winds."},{"type":"Sleep Breath","kind":"Su","details":"Instead of a line of fire, a brass dragon can breathe a cone of sleep gas. Creatures within the cone must succeed on a Will save or fall asleep for 1d6 rounds plus 1 round per age category of the dragon."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A brass dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. Very young—speak with animals; Juvenile—endure elements; Adult-suggestion; Old-control winds; Ancient-control weather; Great wyrm-whirlwind."},{"type":"Summon Djinni","kind":"Sp","details":"This ability, usable by a great wyrm brass dragon once per day, works like a summon monster spell, except that it summons one noble djinni. This ability is the equivalent of a 9th-level spell. Age Category S pecial Abilities C aster Level Wyrmling Fire subtype, sleep breath - Very young speak with animals - Young Move sand 1st Juvenile Desert wind, endure elements 3rd Young adult DR 5/magic, spell resistance 5th Adult frightful presence, suggestion 7th Mature adult DR 10/magic 9th Old Fire aura, control winds 11th Very old DR 15/magic 13th Ancient Sandstorm, control weather 15th Wyrm DR 20/magic 17th Great wyrm Summon djinni, whirlwind 19th."}],"description":"Consummate conversationalists, brass dragons prefer to talk instead of fight. Brass dragons lair near humanoid settlements, where they can hear the most recent news and gossip.","ecology":"","habitat_society":""},{"name":"Ancient Brine Dragon","cr":16,"xp":76800,"alignment":"LN","size":"Huge","type":"dragon","subtypes":["extraplanar","water"],"init":3,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (300 ft., DC 26)"],"ac":37,"ac_touch":7,"ac_flat_footed":37,"ac_mods":"-1 Dex, +30 natural, -2 size","hp":275,"hd":"22d12+132","hdvalue":22,"fort":19,"ref":14,"will":18,"dr":"15/magic","immunities":["acid","paralysis","sleep"],"sr":27,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"swim","speed":60}],"melee":"bite +34 (2d8+21 plus 1d2 Str), 2 claws +34 (2d6+14), tail slap +29 (2d6+21), 2 wings +29 (1d8+7)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"100-ft. line, 20d6 acid, DC 27"},{"type":"capsize"},{"type":"crush"},{"type":"desiccating bite"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":28,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"obscuring mist"},{"spell":"speak with animals","details":"fish only"},{"spell":"water breathing"}]},{"frequency":"3/day","spells":[{"spell":"horrid wilting"}]}],"spellsknown_caster_level":15,"spellsknown_concentration":21,"spellsknown":[{"spell_level":7,"spell_slots":4,"spells":[{"spell":"control weather"},{"spell":"mass fly"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"fluid form"},{"spell":"true seeing"},{"spell":"transformation"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"break enchantment"},{"spell":"dismissal"},{"spell":"teleport"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"ball lightning"},{"spell":"ice storm"},{"spell":"greater invisibility"},{"spell":"solid fog"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"aqueous orb"},{"spell":"deep slumber"},{"spell":"dispel magic"},{"spell":"sleet storm"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"alter self"},{"spell":"detect thoughts"},{"spell":"invisibility"},{"spell":"make whole"},{"spell":"slipstream"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"color spray"},{"spell":"feather fall"},{"spell":"flare burst"},{"spell":"ray of enfeeblement"},{"spell":"touch of the sea"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/ close"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":38,"dexterity":9,"constitution":23,"intelligence":23,"wisdom":20,"charisma":21,"baseatk":22,"cmb":38,"cmd":47,"cmd_special":"+4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Greater Vital Strike"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Swim)"},{"feat":"Vital Strike"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":30},{"skill":"Fly","value":16},{"skill":"Heal","value":30},{"skill":"Knowledge (arcana)","value":31},{"skill":"Knowledge (geography)","value":31},{"skill":"Knowledge (nature)","value":31},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":30},{"skill":"Survival","value":30},{"skill":"Swim","value":53},{"skill":"Use Magic Device","value":30}],"languages":["Aquan","Common","Draconic","Dwarven","Elven","Gnome","Halfling"],"sq":[{"type":"water breathing"}],"environments":["any (Plane of Water)"],"organizations":["solitary"],"treasure":"triple","description_visual":"A blue-green neck frill sweeps back from the head of this dragon, leading to a body of shiny scales and fin-like crests.","group":"Primal Dragon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Capsize","kind":"Ex","details":"An old or older brine dragon can attempt to capsize a boat or ship by ramming it as a charge attack and making a CMB check. The DC of this check is 25 or the result of the boat captain's Profession (sailor) check, whichever is higher. For each size category larger the ship is than the brine dragon's size, the dragon takes a cumulative -10 penalty on the check."},{"type":"Desiccating Bite","kind":"Su","details":"An ancient brine dragon's bite causes weakness, dealing 1d2 points of Strength drain in addition to its normal damage. A great wyrm's bite deals 1d4 points of Strength drain. A Fortitude save (DC equals the dragon's breath weapon save DC) negates the Strength drain."},{"type":"Painful Strikes","kind":"Su","details":"A great wyrm brine dragon's natural attacks are so laden with salt and acidic crystals that every time it strikes a creature with one of these attacks, the target must make a Fortitude save (DC equals the dragon's breath weapon save DC) or be stunned for a round from the pain."},{"type":"Spell-like Abilities","kind":"Sp","details":"A brine dragon gains the following spell-like abilities, usable at will (unless indicated otherwise) at the listed age. Very young-speak with animals (fish only); Young-obscuring mist; Juvenile-water breathing; Adult-control water; Ancient-horrid wilting (3/day); Great wyrm-tsunami (3/day)."}],"description":"Although not inherently evil, brine dragons have little patience for kindness and philanthropy. As they age, they grow more and more opinionated and obsessed with power-by adult age, a brine dragon counts itself a failure if it doesn't rule over a collection of \"lesser beings\" such as humans, merfolk, locathah, or even sahuagin.","ecology":"","habitat_society":""},{"name":"Ancient Underworld Dragon","cr":16,"xp":76800,"alignment":"LE","size":"Huge","type":"dragon","subtypes":["fire"],"init":3,"senses":[{"type":"dragon senses"},{"type":"smoke vision"}],"auras":["frightful presence (300 ft., DC 26)"],"ac":39,"ac_touch":7,"ac_flat_footed":39,"ac_mods":"-1 Dex, +32 natural, -2 size","hp":297,"hd":"22d12+154","hdvalue":22,"fort":20,"ref":12,"will":18,"dr":"15/magic","immunities":["fire","paralysis","sleep"],"sr":27,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"burrow","speed":60},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +33 (2d8+18), 2 claws +33 (2d6+12/19-20), gore +32 (2d6+18), tail slap +27 (2d6+18)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"adamantine claws"},{"type":"breath weapon","details":"100-ft. line, 20d6 fire damage, DC 28"},{"type":"crush","details":"DC 28, 2d8+12"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"repel metal or stone"},{"spell":"soften earth and stone"},{"spell":"spike stones"},{"spell":"stone shape"},{"spell":"wall of stone"}]}],"spellsknown_caster_level":13,"spellsknown_concentration":20,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"disintegrate"},{"spell":"flesh to stone"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"passwall"},{"spell":"transmute rock to mud"},{"spell":"waves of fatigue"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"enervation"},{"spell":"shout"},{"spell":"solid fog"},{"spell":"stone shape"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"displacement"},{"spell":"fireball"},{"spell":"protection from good"},{"spell":"rage"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"acid arrow"},{"spell":"daze monster"},{"spell":"flaming sphere"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"burning hands"},{"spell":"cause fear magic missile"},{"spell":"ray of enfeeblement"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":35,"dexterity":8,"constitution":25,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":22,"cmb":36,"cmb_special":"+2 vs. bull rush","cmd":45,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Armor"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":21,"special":"+25 when jumping"},{"skill":"Appraise","value":30},{"skill":"Bluff","value":30},{"skill":"Climb","value":37},{"skill":"Fly","value":16},{"skill":"Intimidate","value":30},{"skill":"Knowledge (dungeoneering)","value":30},{"skill":"Knowledge (geography)","value":30},{"skill":"Knowledge (planes)","value":30},{"skill":"Perception","value":30},{"skill":"Stealth","value":22}],"languages":["Common","Draconic","Dwarven","Giant","Ignan","Terran"],"sq":[{"type":"change shape"},{"type":"underworld burrower"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"triple","description_visual":"This serpentine dragon has skin the color of deep volcanic rock, enormous claws, and jagged, stonelike horns and scales.","group":"Imperial Dragon","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Adamantine Claws","kind":"Ex","details":"The claws of an underworld dragon are made of adamantine, and have the qualities of a weapon made from that material."},{"type":"Change Shape","kind":"Su","details":"A young or older underworld dragon can assume any humanoid form three times per day as if using polymorph."},{"type":"Lava Eruption","kind":"Su","details":"As a full-round action, a great wyrm underworld dragon can burrow through the ground up to twice its burrow speed. At the end of that movement, if the underworld dragon has use of its breath weapon, it can emerge from the ground spouting lava in a 30-foot-radius burst, dealing damage as the breath weapon."},{"type":"Smoke Vision","kind":"Ex","details":"A very young and older underworld dragon can see perfectly in smoky conditions (such as those created by pyrotechnics)."},{"type":"Underworld Burrower","kind":"Ex","details":"An adult underworld dragon gains a 10-foot bonus to its burrow speed. When the underworld dragon becomes old and every two age categories thereafter, its burrow speed increases by an additional 10 ft."}],"description":"Underworld dragons-also called futsanglungs-are calculating, greedy creatures that carve great labyrinthine tunnels beneath the world, defending their hidden treasures. Preferring the earth to the heavens, they channel the fires of the world's core within their twisting, stonelike bodies and through flaming breath hot enough to turn granite into slag.","ecology":"","habitat_society":""},{"name":"Annihilator Robot","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"construct","subtypes":["robot"],"init":6,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":31,"ac_touch":9,"ac_flat_footed":28,"ac_mods":"+2 Dex, +1 dodge, +22 natural, -4 size","hp":250,"hd":"20d10+60 (+80 force field)","hdvalue":20,"fort":8,"ref":8,"will":7,"defensive_abilities":["hardness 10"],"immunities":["cold","construct traits"],"resists":[{"type":"electricity","value":30},{"type":"fire","value":30}],"weaknesses":["vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"land","speed":50},{"type":"climb","speed":30}],"speed_mod":"booster jets","melee":"2 claws +28 (2d6+12/19-20)","ranged":"2 integrated chain guns +19 (8d6/4)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"combined arms"},{"type":"plasma lance"},{"type":"suppressing fire"}],"strength":34,"dexterity":15,"intelligence":14,"wisdom":13,"charisma":1,"baseatk":20,"cmb":36,"cmd":53,"cmd_special":"+8 vs. trip","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (chain gun)"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Skill Focus (Acrobatics)"},{"feat":"Weapon Focus (chain gun)"}],"skills":[{"skill":"Acrobatics","value":28,"special":"+36 when jumping"},{"skill":"Climb","value":20},{"skill":"Intimidate","value":15},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":24}],"languages":["Common","Hallit"],"environments":["any (Numeria)"],"organizations":["solitary"],"treasure":"none","description_visual":"This towering, scorpion-like construct makes tortured shrieks as it moves, its metallic weapons thrumming with otherworldly energy.","group":"Robot","source":"Inner Sea Bestiary","special_abilities":[{"type":"Booster Jets","kind":"Ex","details":"As a swift action up to 10 times per hour, an annihilator robot can gain a fly speed of 60 ft. (poor maneuverability) for a duration of 1 minute."},{"type":"Chain Guns","kind":"Ex","details":"These advanced firearms have a range increment of 200 ft., automatically reload as a free action, and never misfire. An annihilator's core can process scrap metal into new ammunition, effectively giving the annihilator infinite ammo with these weapons."},{"type":"Combined Arms","kind":"Ex","details":"When taking a full attack action, an annihilator can attack with melee and ranged integrated weapons simultaneously."},{"type":"Plasma Lance","kind":"Ex","details":"As a standard action once every 3 rounds, an annihilator may fire a 120-foot-long line of plasma from its tail. All creatures in this area take 20d6 points of plasma damage (Reflex DC 22 halves). The save DC is Intelligence-based."},{"type":"Suppressing Fire","kind":"Ex","details":"As a standard action, an annihilator can use its chain guns to fire in a 100-foot cone. When it does so, it makes a single chain gun attack against every target in this area."}],"description":"The first known annihilator rampaged through western Numeria in 4709 ar, destroying dozens of towns and villages before retreating with more than a dozen prisoners into the Felldales. Since then, increasing numbers of these immense and devastating robots have been spotted in the region. Annihilators seem driven to destroy structures and slaughter living foes, yet they often gather up the dying and unconscious from battlefields-their purpose for keeping these battered but still-living prisoners is unknown.","ecology":"","habitat_society":""},{"name":"Astradaemon","cr":16,"xp":76800,"alignment":"NE","size":"Large","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"deathwatch"},{"type":"true seeing"}],"auras":["soul siphon (10 ft.)"],"ac":29,"ac_touch":17,"ac_flat_footed":21,"ac_mods":"+7 Dex, +1 dodge, +12 natural, -1 size","hp":212,"hd":"17d10+119","hdvalue":17,"fort":12,"ref":17,"will":14,"defensive_abilities":["displacement"],"dr":"10/good and silver","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":27,"speed":[{"type":"land","speed":90},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"bite +23 (2d6+5 plus energy drain and grab), 2 claws +23 (1d8+5 plus energy drain), tail slap +18 (1d12+2 plus energy drain)","space":"10 ft.","reach":"10 ft. (15 ft. with tail)","special_attacks":[{"type":"devour soul"},{"type":"energy drain","details":"1 level, DC 25"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch"},{"spell":"displacement"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"enervation"},{"spell":"fear"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"vampiric touch"}]},{"frequency":"1/day","spells":[{"spell":"energy drain"},{"spell":"finger of death"},{"spell":"summon","details":"level 6, 1d3 derghodaemons 50%"}]},{"frequency":"3/day","spells":[{"spell":"locate creature"},{"spell":"plane shift"}]}],"strength":21,"dexterity":25,"constitution":24,"intelligence":14,"wisdom":15,"charisma":24,"baseatk":17,"cmb":23,"cmd":41,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Nimble Moves"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":24,"special":"+48 jump"},{"skill":"Escape Artist","value":27},{"skill":"Fly","value":9},{"skill":"Intimidate","value":27},{"skill":"Knowledge (planes)","value":22},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":22},{"skill":"Stealth","value":23},{"skill":"Survival","value":22}],"languages":["Abyssal","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)","any (Astral Plane)"],"organizations":["solitary","pair","pack (3-6)"],"treasure":"standard","description_visual":"Vaguely humanoid in shape, this gaunt fiend has the face of a hideous fish and a body of lanky limbs and writhing tendrils.","group":"Daemon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Devour Soul","kind":"Su","details":"As a standard action, an astradaemon that begins its turn with a grappled opponent can attempt to draw out and consume the soul of its victim, killing it instantly. This ability only works on living creatures, which may resist with a DC 25 Fortitude saving throw. The save is Constitution-based. For every 5 HD of the slain creature, the daemon gains a +1 profane bonus on attacks, saving throws, and checks for 24 hours. This ability doesn't consume all of the soul, and pieces of it still exist after the daemon completes its feast (enough to be able to resurrect the slain victim normally)."},{"type":"Soul Siphon","kind":"Su","details":"If a Small or larger living creature dies within 10 ft. of an astradaemon, the daemon gains 1d8 temporary hit points and a +2 bonus to Strength for 10 minutes. These bonuses stack with themselves. Incorporeal undead and living spirits traveling outside the body (such as a person using astral projection or magic jar) take 1d8 points of damage each round within the daemon's aura."}],"description":"Believed to be creations of the Four Horsemen, astradaemons live out their existence in search of souls to harvest. These deadly creatures are ravening planar predators, openly hunting throughout the void for souls on which to feed. These voracious creatures are the personifications of death resulting from negative energy or level drain. Their vile touch drains life force from their enemies, and even perishing near them sates their thirst for life and souls.","ecology":"","habitat_society":""},{"name":"Belier Devil","cr":16,"xp":76800,"alignment":"LE","size":"Large","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":33,"ac_touch":15,"ac_flat_footed":27,"ac_mods":"+6 Dex, +18 natural, -1 size","hp":212,"hd":"17d10+119","hdvalue":17,"fort":17,"ref":11,"will":20,"dr":"10/good and silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":28,"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"bite +23 (4d8+7), 3 tongues +23 (2d6+7/19-20 plus grab)","space":"10 ft.","reach":"10 ft. (20 ft. with tongues)","special_attacks":[{"type":"blood drain","details":"1d4 Con damage"},{"type":"constrict","details":"1d6+7"},{"type":"possession"},{"type":"strangle"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"acid arrow"},{"spell":"greater dispel magic"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"persistent image"}]},{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"demand"},{"spell":"magic jar"},{"spell":"plane shift"},{"spell":"summon","details":"level 6, 3 barbed devils 45%"},{"spell":"waves of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"acid fog"},{"spell":"dimensional anchor"},{"spell":"dominate person"},{"spell":"greater scrying"},{"spell":"mass suggestion"}]}],"strength":24,"dexterity":23,"constitution":25,"intelligence":25,"wisdom":26,"charisma":24,"baseatk":17,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":41,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Greater Disarm"},{"feat":"Greater Trip"},{"feat":"Improved Critical (tongue)"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"},{"feat":"Iron Will"}],"skills":[{"skill":"Appraise","value":24},{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":27},{"skill":"Fly","value":32},{"skill":"Intimidate","value":24},{"skill":"Knowledge (arcana)","value":27},{"skill":"Knowledge (local)","value":27},{"skill":"Knowledge (nobility)","value":27},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":28},{"skill":"Spellcraft","value":24},{"skill":"Stealth","value":22}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary"],"treasure":"double","description_visual":"This amphisbaenic monstrosity has the body of a slug with a leech's mouth at one end and a knot of three human heads at the other.","group":"Devil","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Possession","kind":"Su","details":"When a belier devil uses its magic jar spell-like ability, it can identify and pinpoint life forces accurately, allowing it to select its victims with ease. It doesn't require a receptacle to use magic jar. If it uses magic jar on a host while on the Material Plane, its own body becomes ethereal for the duration of the possession and the magic jar effect lasts until the effect is dispelled, the devil ends the effect, it is forced out of its host body, or it or its host body is slain."}],"description":"Masterful possessors and foul manipulators, belier devils are among the most feared masterminds of Hell. Known as bdellavritras to devilkind, these worm-like fiends avoid physical confrontation. Instead, they target inf luential individuals for possession, using them to manipulate events by proxy. If their schemes are uncovered, the devils retaliate with all the power at their host bodies' disposal.\n\nA bdellavritra's voice can emanate from its worm-like maw, from any of its human-like mouths, or from all four at once, as it desires. Each mouth has its own distinct voice, often pleasing to the human ear. Bdellavritras typically reach lengths of 16 ft. from worm-mouth to human heads, and weigh 3,000 pounds.","ecology":"","habitat_society":""}];
